/*! Open Historia - deterministic GM preview revisions (AGPL-3.0-or-later). */
import { EVENT_IMPACT_KEYS } from "../../runtime/eventImpactKeys.js";

// A revision only edits paths in a previously validated pending transaction.
// This is deliberately NOT a second complete transaction generated by the AI:
// every unmentioned event and operation remains byte-for-byte equivalent.
const LEDGER_FAMILIES = new Set([
  "countryStatPatches", "storylineUpdates", "warUpdates", "relationUpdates",
  "agreementUpdates", "puppetUpdates", "diplomaticOutreach",
]);
const EDITABLE_EVENT_FIELDS = new Set([
  "title", "description", "date", "importance", "kind", "tags",
  "notable", "playerRelated", "warId", "combatants",
]);
const IMPACT_FAMILIES = new Set(EVENT_IMPACT_KEYS.filter((key) => key !== "actionIds"));
const UNSAFE_KEYS = new Set(["__proto__", "prototype", "constructor"]);
const MAX_EDITS = 24;
const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
const isRecord = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
const clone = (value) => JSON.parse(JSON.stringify(value));
const indexOf = (part) => /^(0|[1-9][0-9]*)$/.test(part) ? Number(part) : -1;

export const GAME_MASTER_EDIT_TOOL = Object.freeze({
  name: "submit_game_master_preview_edits",
  description: "Submit only changes to the existing, un-applied Game Master preview; the game preserves all unmentioned operations.",
  schema: {
    type: "object",
    properties: {
      edits: {
        type: "array",
        minItems: 1,
        maxItems: MAX_EDITS,
        items: {
          type: "object",
          properties: {
            op: { type: "string", enum: ["replace", "add", "remove"] },
            path: { type: "string", description: "JSON Pointer into the CURRENT preview transaction (e.g. /events/0/impacts/politicalActorOps/0/argsJson/office)." },
            valueJson: { type: "string", description: "JSON-encoded replacement or added value. For remove use an empty string." },
          },
          required: ["op", "path", "valueJson"],
          additionalProperties: false,
        },
      },
    },
    required: ["edits"],
    additionalProperties: false,
  },
});

export const validateGameMasterEditResponse = (response) => {
  if (!isRecord(response) || Object.keys(response).some((key) => key !== "edits")) {
    return { valid: false, error: "GM edit response must contain only edits." };
  }
  const edits = response.edits;
  if (!Array.isArray(edits) || !edits.length || edits.length > MAX_EDITS) {
    return { valid: false, error: "GM edit response requires 1-24 targeted operations." };
  }
  for (const [index, edit] of edits.entries()) {
    if (!isRecord(edit) || Object.keys(edit).some((key) => !["op", "path", "valueJson"].includes(key))
      || !["replace", "add", "remove"].includes(edit.op)
      || typeof edit.path !== "string" || !edit.path.startsWith("/") || edit.path.length > 256
      || typeof edit.valueJson !== "string") {
      return { valid: false, error: `edits[${index}] must specify op, JSON Pointer path, and valueJson.` };
    }
    if (edit.op !== "remove") {
      try { JSON.parse(edit.valueJson); }
      catch { return { valid: false, error: `edits[${index}].valueJson is not valid JSON.` }; }
    }
  }
  return { valid: true, error: "" };
};

const pointer = (path) => {
  if (typeof path !== "string" || !path.startsWith("/") || path.length > 256) {
    throw new Error("GM edit path must be a JSON Pointer into the existing transaction.");
  }
  const parts = path.slice(1).split("/").map((part) => {
    if (/~(?![01])/.test(part)) throw new Error("Invalid JSON Pointer escape.");
    const decoded = part.replace(/~1/g, "/").replace(/~0/g, "~");
    if (!decoded || UNSAFE_KEYS.has(decoded)) throw new Error("Unsafe or empty GM edit path segment.");
    return decoded;
  });
  if (parts[0] === "summary" && parts.length === 1) return parts;
  if (LEDGER_FAMILIES.has(parts[0]) && parts.length >= 2 && (indexOf(parts[1]) >= 0 || parts[1] === "-")) return parts;
  if (parts[0] !== "events" || parts.length < 3 || indexOf(parts[1]) < 0) {
    throw new Error(`GM edit cannot modify immutable transaction root ${parts[0]}.`);
  }
  if (EDITABLE_EVENT_FIELDS.has(parts[2]) && parts.length === 3) return parts;
  if (parts[2] === "impacts" && parts.length >= 5 && IMPACT_FAMILIES.has(parts[3])
    && (indexOf(parts[4]) >= 0 || parts[4] === "-")) return parts;
  throw new Error("GM edit may change an event field or a particular canonical operation, not replace events/impacts wholesale.");
};

// Edits to a politicalActorOps argsJson field may address its decoded fields.
// The field is reserialized only after a successful replacement, never on a
// failed edit (so the previous preview can still be approved untouched).
const patchAt = (root, parts, { op, valueJson }) => {
  let node = root;
  let encodedOwner = null;
  for (let i = 0; i < parts.length - 1; i += 1) {
    const part = parts[i];
    if (Array.isArray(node)) {
      const index = indexOf(part);
      if (index < 0 || index >= node.length) throw new Error(`GM edit target ${part} is not an existing array item.`);
      node = node[index];
    } else if (isRecord(node) && own(node, part)) {
      if (part === "argsJson" && typeof node[part] === "string" && i < parts.length - 1) {
        const encoded = node;
        let parsed;
        try { parsed = JSON.parse(encoded.argsJson); }
        catch { throw new Error("Cannot edit malformed political operation argsJson."); }
        if (!isRecord(parsed)) throw new Error("Political operation argsJson is not an object.");
        encodedOwner = { target: encoded, decoded: parsed };
        node = parsed;
      } else {
        node = node[part];
      }
    } else {
      throw new Error(`GM edit target ${part} does not exist.`);
    }
  }
  const key = parts.at(-1);
  const value = op === "remove" ? undefined : JSON.parse(valueJson);
  if (Array.isArray(node)) {
    if (op === "add" && key === "-") node.push(value);
    else {
      const index = indexOf(key);
      if (index < 0 || index >= node.length || op === "add") throw new Error("Array operations must replace/remove an existing item or append with /-.");
      if (op === "remove") node.splice(index, 1);
      else node[index] = value;
    }
  } else if (isRecord(node)) {
    if (op === "replace" && !own(node, key)) throw new Error(`GM edit cannot replace absent field ${key}.`);
    if (op === "remove" && !own(node, key)) throw new Error(`GM edit cannot remove absent field ${key}.`);
    if (op === "add" && own(node, key)) throw new Error(`GM edit cannot add field ${key} twice.`);
    if (op === "remove") delete node[key];
    else node[key] = value;
  } else {
    throw new Error("GM edit target is not an object or array.");
  }
  if (encodedOwner) encodedOwner.target.argsJson = JSON.stringify(encodedOwner.decoded);
};

export const applyGameMasterPreviewEdits = (transaction, response) => {
  const verdict = validateGameMasterEditResponse(response);
  if (!verdict.valid) throw new Error(verdict.error);
  if (!isRecord(transaction) || !Array.isArray(transaction.events)) throw new Error("Missing validated GM transaction.");
  const next = clone(transaction);
  for (const edit of response.edits) {
    const parts = pointer(edit.path);
    if (parts.at(-1) === "-" && edit.op !== "add") throw new Error("/- is only for append operations.");
    if (parts[0] === "summary" && (edit.op !== "replace" || typeof JSON.parse(edit.valueJson) !== "string")) {
      throw new Error("GM summary must be replaced with plain text.");
    }
    if (parts[0] === "events" && parts[2] !== "impacts" && edit.op !== "replace") {
      throw new Error("Existing event fields can only be replaced.");
    }
    if (parts[0] === "events" && indexOf(parts[1]) >= transaction.events.length) {
      throw new Error("GM edit cannot invent event indexes; generate a new preview for additional events.");
    }
    patchAt(next, parts, edit);
  }
  if (JSON.stringify(next) === JSON.stringify(transaction)) throw new Error("GM edits did not change the preview.");
  return next;
};
